import heapq

def spread_shifts(shifts):
    left = {}
    for ch in shifts:
        left[ch] = left.get(ch, 0) + 1
    heap = [(-c, ch) for ch, c in left.items()]
    heapq.heapify(heap)
    rota = []
    while heap:
        c, ch = heapq.heappop(heap)
        if rota and rota[-1] == ch:
            if not heap:
                return ''
            c2, ch2 = heapq.heappop(heap)
            heapq.heappush(heap, (c, ch))
            c, ch = c2, ch2
        rota.append(ch)
        if c + 1 < 0:
            heapq.heappush(heap, (c + 1, ch))
    return ''.join(rota)

