import heapq

def spread_shifts(shifts):
    left = {}
    for ch in shifts:
        left[ch] = left.get(ch, 0) + 1
    heap = [(-c, -ord(ch)) for ch, c in left.items()]
    heapq.heapify(heap)
    rota = []
    while heap:
        c, k = heapq.heappop(heap)
        ch = chr(-k)
        if rota and rota[-1] == ch:
            if not heap:
                return ''
            c2, k2 = heapq.heappop(heap)
            heapq.heappush(heap, (c, k))
            c, k, ch = c2, k2, chr(-k2)
        rota.append(ch)
        if c + 1 < 0:
            heapq.heappush(heap, (c + 1, k))
    return ''.join(rota)

def spread_shifts(shifts):
    n = len(shifts)
    left = {}
    for ch in shifts:
        left[ch] = left.get(ch, 0) + 1
    if not n or max(left.values()) > (n + 1) // 2:
        return ''
    order = sorted(left, key=lambda ch: (-left[ch], ch))
    slots = list(range(0, n, 2)) + list(range(1, n, 2))
    rota = [''] * n
    i = 0
    for ch in order:
        for _ in range(left[ch]):
            rota[slots[i]] = ch
            i += 1
    return ''.join(rota)
